#!/bin/bash

NAME=flower_scattering BLEND_DIR=blend DEST=drive/MyDrive/code/outputs/blender bash -c 'mkdir -p "$DEST" logs; blender -b "${BLEND_DIR}/${NAME}.blend" -E CYCLES -x 1 -o "//${NAME}" -F PNG -a -- --cycles-device CUDA+CPU --profile-gpu >"logs/${NAME}.log" 2>&1 & bpid=$!; (while kill -0 "$bpid" 2>/dev/null; do printf "[%s] mover alive; checking for %s*.png\n" "$(date "+%F %T")" "$NAME"; for f in "${NAME}"*.png; do [ -f "$f" ] || continue; size1=$(stat -c%s "$f" 2>/dev/null) || continue; sleep 2; size2=$(stat -c%s "$f" 2>/dev/null) || continue; if [ "$size1" = "$size2" ]; then mv -- "$f" "$DEST/"; printf "[%s] moved %s (%s bytes)\n" "$(date "+%F %T")" "$f" "$size2"; fi; done; sleep 10; done; printf "[%s] blender finished; final move\n" "$(date "+%F %T")"; for f in "${NAME}"*.png; do [ -f "$f" ] || continue; size1=$(stat -c%s "$f" 2>/dev/null) || continue; sleep 2; size2=$(stat -c%s "$f" 2>/dev/null) || continue; [ "$size1" = "$size2" ] && mv -- "$f" "$DEST/" && printf "[%s] final move: %s (%s bytes)\n" "$(date "+%F %T")" "$f" "$size2"; done) >"logs/${NAME}-mover.log" 2>&1 &'
